package com.mycompany.rentalmanagement.servlet;import com.mycompany.rentalmanagement.dao.DashboardDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{DashboardDAO d=new DashboardDAO();r.setAttribute("stats",d.stats());r.setAttribute("recent",d.recent());r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}}
